CREATE EXTENSION IF NOT EXISTS pgcrypto;

DO $$ BEGIN
  CREATE TYPE user_role AS ENUM ('platform_admin', 'tenant_admin', 'analyst', 'customer');
  CREATE TYPE account_status AS ENUM ('invited', 'active', 'disabled', 'locked');
  CREATE TYPE upload_status AS ENUM ('staged', 'validated', 'rejected', 'processed');
  CREATE TYPE report_status AS ENUM ('draft', 'published', 'archived');
  CREATE TYPE audit_severity AS ENUM ('info', 'warning', 'critical');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

CREATE TABLE IF NOT EXISTS tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(160) NOT NULL, code varchar(48) UNIQUE NOT NULL, status varchar(24) NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid REFERENCES tenants(id) ON DELETE RESTRICT, email varchar(320) NOT NULL UNIQUE, display_name varchar(160) NOT NULL, password_hash text, role user_role NOT NULL DEFAULT 'customer', status account_status NOT NULL DEFAULT 'invited', auth_provider varchar(32) NOT NULL DEFAULT 'local', mfa_secret_encrypted text, mfa_required boolean NOT NULL DEFAULT true, backup_codes_hash jsonb NOT NULL DEFAULT '[]', failed_sign_in_count integer NOT NULL DEFAULT 0, locked_until timestamptz, last_signed_in_at timestamptz, disabled_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS dataset_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(160) NOT NULL, schema_mapping jsonb NOT NULL, outcome_codes jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS uploads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid REFERENCES tenants(id) ON DELETE RESTRICT, template_id uuid REFERENCES dataset_templates(id) ON DELETE RESTRICT, storage_key text NOT NULL, sha256 varchar(64) NOT NULL UNIQUE, source_filename varchar(255) NOT NULL, source_month integer NOT NULL CHECK (source_month BETWEEN 1 AND 12), source_year integer NOT NULL CHECK (source_year BETWEEN 2000 AND 2200), record_count integer NOT NULL DEFAULT 0, status upload_status NOT NULL DEFAULT 'staged', validation_results jsonb NOT NULL DEFAULT '{}', uploaded_by uuid REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outreach_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), upload_id uuid NOT NULL REFERENCES uploads(id) ON DELETE CASCADE, call_id varchar(100) NOT NULL, member_id varchar(100), renewal_date timestamptz, reachable boolean, call_status_code varchar(24), attempt_one_code integer, attempt_two_code integer, attempt_three_code integer, raw_fields jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title varchar(180) NOT NULL, description text, template_id uuid REFERENCES dataset_templates(id) ON DELETE RESTRICT, layout_config jsonb NOT NULL DEFAULT '{}', status report_status NOT NULL DEFAULT 'draft', version integer NOT NULL DEFAULT 1, created_by uuid REFERENCES users(id) ON DELETE RESTRICT, published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS report_publications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL REFERENCES reports(id) ON DELETE CASCADE, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, authorized_periods jsonb NOT NULL DEFAULT '[]', published_by uuid REFERENCES users(id) ON DELETE RESTRICT, published_at timestamptz NOT NULL DEFAULT now(), UNIQUE(report_id, tenant_id));
CREATE TABLE IF NOT EXISTS audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), occurred_at timestamptz NOT NULL DEFAULT now(), request_id varchar(64) NOT NULL, actor_id uuid REFERENCES users(id) ON DELETE SET NULL, tenant_id uuid REFERENCES tenants(id) ON DELETE SET NULL, action varchar(96) NOT NULL, severity audit_severity NOT NULL DEFAULT 'info', resource_type varchar(64) NOT NULL, resource_id varchar(128), ip_hash varchar(96) NOT NULL, user_agent varchar(512), method varchar(12) NOT NULL, status_code integer NOT NULL, before_state jsonb, after_state jsonb, metadata jsonb NOT NULL DEFAULT '{}');
CREATE INDEX IF NOT EXISTS audit_occurred_idx ON audit_events(occurred_at DESC); CREATE INDEX IF NOT EXISTS audit_actor_idx ON audit_events(actor_id); CREATE INDEX IF NOT EXISTS audit_action_idx ON audit_events(action); CREATE INDEX IF NOT EXISTS users_tenant_idx ON users(tenant_id); CREATE INDEX IF NOT EXISTS outreach_records_upload_idx ON outreach_records(upload_id); CREATE INDEX IF NOT EXISTS outreach_records_status_idx ON outreach_records(call_status_code);

CREATE OR REPLACE FUNCTION prohibit_audit_mutation() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'audit_events is append-only'; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS audit_events_immutable ON audit_events;
CREATE TRIGGER audit_events_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION prohibit_audit_mutation();

ALTER TABLE tenants ENABLE ROW LEVEL SECURITY; ALTER TABLE users ENABLE ROW LEVEL SECURITY; ALTER TABLE uploads ENABLE ROW LEVEL SECURITY; ALTER TABLE reports ENABLE ROW LEVEL SECURITY; ALTER TABLE report_publications ENABLE ROW LEVEL SECURITY; ALTER TABLE audit_events ENABLE ROW LEVEL SECURITY;
-- The application connects through a non-owner role in production and sets app.tenant_id per transaction before tenant-scoped queries.
